local_reproduction_script:
const fs = require('node:fs');
const { createRequire } = require('node:module');
const rootRequire = createRequire(process.cwd() + '/package.json');
const nestedRequire = createRequire(rootRequire.resolve('vite-plugin-dynamic-import'));
const braces = rootRequire('braces');
const cases = [
  ['braces.compile', (s) => braces(s)],
  ['braces.expand', (s) => braces.expand(s)],
  ['fast-glob@3.3.1.generateTasks', (s) => rootRequire('fast-glob').generateTasks(s)],
  ['fast-glob@3.3.3.generateTasks', (s) => nestedRequire('fast-glob').generateTasks(s)],
];
const results = [];
for (const [name, fn] of cases) {
  for (const [kind, pattern] of [
    ['ordinary', 'app/{page,layout}.tsx'],
    ['nested-braces', '{'.repeat(4500) + 'a,b' + '}'.repeat(4500)],
    ['nested-parentheses', '('.repeat(4500) + 'a' + ')'.repeat(4500)],
  ]) {
    try {
      const value = fn(pattern);
      results.push({ name, kind, length: pattern.length, outcome: 'RETURNED', resultCount: value.length });
    } catch (error) {
      results.push({ name, kind, length: pattern.length, outcome: error.name, message: error.message });
    }
  }
}
const result = { node: process.version, method: 'Local synchronous calls; exceptions caught; no HTTP exploit or uncaught service crash.', results };
fs.writeFileSync(__dirname + '/reproduction.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result, null, 2));

runtime_instrumentation.esm_load_hook:
import { appendFileSync } from 'node:fs';
export async function load(url, context, nextLoad) {
  const result = await nextLoad(url, context);
  if (url.startsWith('file:')) appendFileSync(process.env.KFM_DEP_TRACE, JSON.stringify({kind:'esm',url}) + '\n');
  return result;
}

runtime_instrumentation.cjs_preload:
const Module = require('node:module');
const fs = require('node:fs');
const original = Module._load;
Module._load = function (request, parent, isMain) {
  const result = original.apply(this, arguments);
  const filename = Module._resolveFilename(request, parent, isMain);
  if (typeof filename === 'string' && filename.startsWith('/')) fs.appendFileSync(process.env.KFM_DEP_TRACE, JSON.stringify({kind:'cjs',url:filename}) + '\n');
  return result;
};
